#!/usr/bin/env bash
# Regenerates src/BuiltinShaders.cpp (the SPIR-V of the engine's built-in shaders) from the
# GLSL sources in this directory. The generated file is committed on purpose: building the
# renderer must not require a shader compiler.
#
# Needs `glslangValidator` (Vulkan SDK, `apt install glslang-tools`, `brew install glslang`)
# and python3. Run from anywhere:   engine/cpp/renderer/shaders/generate_builtin_shaders.sh
set -euo pipefail

here="$(cd "$(dirname "${BASH_SOURCE[0]}")" && pwd)"
out="$here/../src/BuiltinShaders.cpp"
tmp="$(mktemp -d)"
trap 'rm -rf "$tmp"' EXIT

glslangValidator -V --target-env vulkan1.0 -S vert -o "$tmp/colored_mesh.vert.spv" "$here/colored_mesh.vert" >/dev/null
glslangValidator -V --target-env vulkan1.0 -S frag -o "$tmp/colored_mesh.frag.spv" "$here/colored_mesh.frag" >/dev/null

python3 - "$tmp" "$out" <<'PY'
import struct, sys
tmp, out = sys.argv[1], sys.argv[2]

def words(path):
    data = open(path, 'rb').read()
    assert len(data) % 4 == 0
    return struct.unpack('<%dI' % (len(data) // 4), data)

def array(name, ws):
    lines = []
    for i in range(0, len(ws), 8):
        lines.append('    ' + ', '.join('0x%08x' % w for w in ws[i:i + 8]) + ',')
    return 'constexpr std::uint32_t %s[] = {\n%s\n};\n' % (name, '\n'.join(lines))

with open(out, 'w') as f:
    f.write('// GENERATED by shaders/generate_builtin_shaders.sh from shaders/colored_mesh.{vert,frag} - do not edit.\n')
    f.write('#include "renderer/BuiltinShaders.hpp"\n\nnamespace renderer {\n\nnamespace {\n\n')
    f.write(array('kColoredMeshVert', words(tmp + '/colored_mesh.vert.spv')) + '\n')
    f.write(array('kColoredMeshFrag', words(tmp + '/colored_mesh.frag.spv')))
    f.write('\n} // namespace\n\n')
    f.write('std::span<const std::uint32_t> ColoredMeshVertexShader() noexcept\n{\n    return kColoredMeshVert;\n}\n\n')
    f.write('std::span<const std::uint32_t> ColoredMeshFragmentShader() noexcept\n{\n    return kColoredMeshFrag;\n}\n\n')
    f.write('} // namespace renderer\n')
PY
# The CI formatting check covers this file too, so hand it to clang-format when available.
if command -v clang-format >/dev/null 2>&1; then
    clang-format -i "$out"
else
    echo "warning: clang-format not found; run devkit/scripts/format.sh before committing" >&2
fi
echo "wrote $out"
